package com.example.vehicleservice.controller;
import com.example.vehicleservice.dto.CustomerRequest; import com.example.vehicleservice.service.CustomerService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/customers") public class CustomerController {private final CustomerService service;public CustomerController(CustomerService s){service=s;} @PostMapping public ResponseEntity<?> create(@Valid @RequestBody CustomerRequest d){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(d));} @GetMapping public java.util.List<?> all(){return service.all();}}
